n = int(input())
res = []
plus = 0
minus = 0
rounds = []
s = input()
q = int(input())
while q > 0:
	x = input().split(' ')
	(first, second) = (int(x[0]), int(x[1]))
	rounds.append(sorted([first, second]))
	q -= 1
for i in range(len(s)):
	if s[i] == '+':
		plus += 1
	if s[i] == '-':
		minus += 1
(max1, min1) = (max(plus, minus), min(plus, minus))
for (min2, max2) in rounds:
	if max1 == min1:
		res.append('YES')
		continue
	if max2 == min2:
		if max1 == min1:
			res.append('YES')
		else:
			res.append('NO')
		continue
	c = max2 * min1 - max1 * min2
	cur = c / (max2 - min2)
	if cur - int(cur) == 0 and cur >= 0:
		res.append('YES')
	else:
		res.append('NO')
for x in res:
	print(x)
